output:
echo -e '#!/bin/bash
OPTS=$(getopt -o f:v --long file:,verbose -n "$0" -- "$@") && eval set -- "$OPTS"
while true; do
  case "$1" in
    -f|--file) FILE="$2"; shift 2;;
    -v|--verbose) VERBOSE=true; shift;;
    --) shift; break;;
  esac
done
echo "File: $FILE, Verbose: $VERBOSE"' > getopt.sh && chmod +x getopt.sh
